$faqs=[
["category"=>"Basics","question"=>"What is a call center?","answer"=>"A call center is an operation that manages customer or prospect interactions by telephone. It uses trained agents, telephony, routing, workforce planning, supervision, quality monitoring, and reporting.","links"=>[]],
["category"=>"Basics","question"=>"What is call center outsourcing?","answer"=>"Call center outsourcing is the use of an external provider to operate defined inbound, outbound, or blended voice services on behalf of a company.","links"=>[["/solutions/customer-experience-solutions","Explore outsourced customer support"]]],
["category"=>"Basics","question"=>"What is the difference between a call center and a contact center?","answer"=>"A call center focuses primarily on telephone interactions. A contact center manages voice plus digital channels such as email, chat, SMS, social messaging, and web or in-app support.","links"=>[]],
["category"=>"Services","question"=>"What is an inbound call center?","answer"=>"An inbound call center receives customer-initiated calls. Common services include customer care, order support, billing questions, reservations, appointment scheduling, technical support, and complaint handling.","links"=>[]],
["category"=>"Services","question"=>"What is an outbound call center?","answer"=>"An outbound call center places calls for activities such as lead qualification, appointment setting, customer follow-up, surveys, renewal outreach, collections support, and service notifications.","links"=>[]],
["category"=>"Services","question"=>"What is a blended call center?","answer"=>"A blended call center handles both inbound and outbound work. Workforce and routing rules allocate agents based on live inbound demand, outbound priorities, skills, and service levels.","links"=>[]],
["category"=>"Staffing","question"=>"How many agents does a call center need?","answer"=>"Staffing depends on contact volume, arrival patterns, average handling time, service level, hours, shrinkage, occupancy, channels, and skill requirements. Workforce planning should use interval-level forecasts rather than simple daily averages.","links"=>[]],
["category"=>"Staffing","question"=>"What is call center shrinkage?","answer"=>"Shrinkage is paid time when agents are unavailable to handle contacts because of training, coaching, meetings, breaks, leave, system issues, or other activities. It must be included in staffing calculations.","links"=>[]],
["category"=>"Staffing","question"=>"What is call center occupancy?","answer"=>"Occupancy is the proportion of logged-in time that agents spend handling contacts or related after-call work. Very high sustained occupancy can increase fatigue and reduce service quality.","links"=>[]],
["category"=>"Coverage","question"=>"Can an outsourced call center provide 24/7 support?","answer"=>"Yes. Providers can use shifts, multiple delivery locations, or follow-the-sun coverage to support nights, weekends, holidays, and continuous operations.","links"=>[["/global-footprint/","Explore delivery locations"]]],
["category"=>"Coverage","question"=>"Can a call center provide multilingual support?","answer"=>"Yes, subject to recruiting availability and program scale. Language requirements should specify proficiency, accent expectations, written capability, hours, and whether each language needs dedicated or shared coverage.","links"=>[]],
["category"=>"Cost","question"=>"How much does call center outsourcing cost?","answer"=>"Typically, cost depends on location, service complexity, hours, language, volume, team model, technology, management, and compliance. Pricing may be per agent, hour, minute, contact, or outcome.","links"=>[["/insights/how-much-does-bpo-cost-2026","Review outsourcing pricing"]]],
["category"=>"Cost","question"=>"What affects call center pricing?","answer"=>"Major cost drivers include delivery market, call complexity, training time, operating schedule, required skills, forecast stability, occupancy, supervision, quality assurance, technology, and security.","links"=>[]],
["category"=>"Technology","question"=>"What technology does a modern call center use?","answer"=>"Common systems include cloud telephony, automatic call distribution, interactive voice response, CRM, ticketing, workforce management, quality monitoring, knowledge management, analytics, recording, and reporting.","links"=>[]],
["category"=>"Technology","question"=>"What is interactive voice response (IVR)?","answer"=>"IVR is an automated phone system that collects caller input and routes or serves the caller based on menu choices, speech, account data, or intent. Good IVR design minimizes effort and preserves access to a person.","links"=>[]],
["category"=>"Technology","question"=>"Can outsourced agents use our phone system and CRM?","answer"=>"Yes. Providers can often use client systems or an approved provider platform. Integration, access, recording, data flow, support ownership, and security responsibilities should be defined before launch.","links"=>[["/compliance-security/","Review security controls"]]],
["category"=>"Metrics","question"=>"What is service level in a call center?","answer"=>"Service level measures the percentage of contacts answered within a defined time. For example, a contract may define a target percentage of calls answered within a specified number of seconds.","links"=>[]],
["category"=>"Metrics","question"=>"What is average handling time?","answer"=>"Average handling time combines talk time, hold time, and after-call work. It is useful for planning, but reducing it without considering quality or resolution can harm the customer experience.","links"=>[]],
["category"=>"Metrics","question"=>"What is call abandonment rate?","answer"=>"Call abandonment rate is the percentage of callers who disconnect before reaching an agent. It is influenced by wait time, routing, announcements, self-service, and caller tolerance.","links"=>[]],
["category"=>"Metrics","question"=>"Which KPIs should a call center track?","answer"=>"Common KPIs include service level, answer speed, abandonment, handling time, first-contact resolution, customer satisfaction, quality score, adherence, occupancy, transfer rate, and repeat contacts.","links"=>[["/solutions/quality-assurance-outsourcing","Explore call center QA"]]],
["category"=>"Quality","question"=>"How are outsourced calls monitored for quality?","answer"=>"Quality teams review recorded or live interactions against an agreed scorecard, calibrate scoring, identify trends, coach agents, and track corrective actions and improvement.","links"=>[["/solutions/quality-assurance-outsourcing","View quality assurance services"]]],
["category"=>"Quality","question"=>"Can AI monitor call center interactions?","answer"=>"AI can help transcribe, categorize, summarize, redact, search, and flag interactions for review. Human quality specialists should validate findings, interpret context, and manage coaching or compliance decisions.","links"=>[["/insights/ai-in-customer-experience-automation","Read about AI in CX"]]],
["category"=>"Implementation","question"=>"How long does it take to launch an outsourced call center?","answer"=>"Time depends on hiring, training, telephony, integrations, scripts, knowledge, security, testing, and team size. Standard programs may launch quickly, while complex regulated operations require more preparation.","links"=>[["/contact","Discuss a call center launch"]]],
["category"=>"Security","question"=>"How is payment or personal data protected on calls?","answer"=>"Controls may include secure access, encryption, recording rules, data masking, clean-desk policies, restricted devices, workforce training, monitoring, and standards such as PCI DSS or applicable privacy requirements.","links"=>[["/compliance-security/","View compliance and security"]]],
["category"=>"Selection","question"=>"How should a company choose a call center outsourcing provider?","answer"=>"Evaluate relevant call types, leadership, hiring, training, workforce planning, technology, quality, reporting, security, continuity, cultural alignment, references, pricing, and scalability.","links"=>[["/about-us","Learn about EmpireOneCX"],["/case-study","View case studies"]]]
